css:
.fx-art{position:relative;overflow:hidden;background:linear-gradient(135deg,var(--primary),color-mix(in srgb,var(--primary) 45%,var(--accent)))}
.fx-art::before,.fx-art::after{content:"";position:absolute;border-radius:50%;background:color-mix(in srgb,var(--accent) 60%,#fff);opacity:.35}
.fx-art::before{width:60%;aspect-ratio:1;right:-12%;top:-20%}.fx-art::after{width:38%;aspect-ratio:1;left:8%;bottom:-18%;opacity:.25;background:#fff}
.fx-art.a2{background:linear-gradient(160deg,var(--accent),color-mix(in srgb,var(--accent) 40%,var(--primary)))}
.fx-art.a3{background:linear-gradient(200deg,color-mix(in srgb,var(--primary) 70%,#000),var(--accent))}
.fx-qv{position:relative;width:min(920px,100%);height:640px;border:1px solid var(--border);border-radius:var(--radius);overflow:hidden;background:color-mix(in srgb,var(--surface) 94%,var(--text))}.fx-qv .btn{display:inline-flex;align-items:center;justify-content:center;gap:.5em;padding:.7em 1.15em;border-radius:var(--radius);font:600 .92em var(--font-body);cursor:pointer;border:1px solid var(--border);background:transparent;color:var(--text);transition:background calc(.2s/var(--speed)),color calc(.2s/var(--speed)),transform calc(.2s/var(--speed)),border-color calc(.2s/var(--speed))}
.fx-qv .btn:hover{border-color:var(--primary);color:var(--primary)}
.fx-qv .btn.pri{background:var(--primary);border-color:var(--primary);color:var(--on-primary)}
.fx-qv .btn.pri:hover{background:color-mix(in srgb,var(--primary) 85%,var(--text));color:var(--on-primary)}
.fx-qv .btn.acc{background:var(--accent);border-color:var(--accent);color:var(--on-accent)}
.fx-qv .btn:active{transform:translateY(1px)}
.fx-qv :focus-visible{outline:2px solid var(--accent);outline-offset:2px}
.fx-qv .scrim{position:absolute;inset:0;z-index:20;display:grid;place-items:center;padding:1em;background:color-mix(in srgb,#0b0e14 48%,transparent);backdrop-filter:blur(2px);visibility:hidden;opacity:0;transition:opacity calc(.25s/var(--speed)),visibility 0s linear calc(.25s/var(--speed))}
.fx-qv .scrim.open{visibility:visible;opacity:1;transition-delay:0s}
.fx-qv .pg{position:absolute;inset:0;padding:1.3em 1.5em;overflow:hidden}
.fx-qv .pg h2{font-size:1.5em;margin-bottom:.9em}
.fx-qv .gr{display:grid;grid-template-columns:repeat(3,1fr);gap:1em}
.fx-qv .th{position:relative;aspect-ratio:4/5;border-radius:var(--radius);overflow:hidden}.fx-qv .th .fx-art{position:absolute;inset:0}
.fx-qv .qvb{position:absolute;left:50%;bottom:.7em;transform:translate(-50%,calc(100% + 1em));white-space:nowrap;padding:.6em 1.1em;border:0;border-radius:99px;background:var(--surface);color:var(--text);font:700 .82em var(--font-body);cursor:pointer;box-shadow:0 8px 20px -8px rgba(0,0,0,.45);transition:transform calc(.35s/var(--speed)) cubic-bezier(.2,.8,.2,1)}
.fx-qv .it:hover .qvb,.fx-qv .qvb:focus-visible{transform:translate(-50%,0)}
@media(hover:none){.fx-qv .qvb{transform:translate(-50%,0)}}
.fx-qv .nm{display:flex;justify-content:space-between;gap:.5em;margin-top:.7em;font-size:.92em}.fx-qv .nm span{font-weight:700}.fx-qv .nm s{opacity:.5;font-weight:400;margin-left:.4em}
.fx-qv .dlg{width:min(720px,100%);max-height:100%;overflow:auto;display:grid;grid-template-columns:1fr 1fr;background:var(--surface);border:1px solid var(--border);border-radius:calc(var(--radius) + 4px);box-shadow:0 30px 60px -20px rgba(0,0,0,.5);transform:translateY(14px) scale(.97);transition:transform calc(.35s/var(--speed)) cubic-bezier(.2,.8,.2,1);position:relative}
.fx-qv .scrim.open .dlg{transform:none}
.fx-qv .dlg>.fx-art{min-height:20em}
.fx-qv .dt{padding:1.6em 1.5em 1.4em;display:grid;gap:.9em;align-content:start}
.fx-qv .dt small{font-size:.74em;font-weight:700;letter-spacing:.1em;text-transform:uppercase;color:var(--accent)}
.fx-qv .dt h3{font-size:1.6em}.fx-qv .stars{font-size:.85em;color:var(--accent);letter-spacing:.1em}.fx-qv .stars span{color:var(--text);opacity:.55;letter-spacing:0;margin-left:.4em}
.fx-qv .pp{font:600 1.4em var(--font-heading)}.fx-qv .pp s{font-size:.7em;opacity:.5;margin-left:.4em;font-weight:400}
.fx-qv .dt p{opacity:.7;font-size:.9em}
.fx-qv .lab{font-size:.74em;font-weight:700;letter-spacing:.08em;text-transform:uppercase;opacity:.65;margin-bottom:.45em}
.fx-qv .opt{display:flex;gap:.45em;flex-wrap:wrap;border:0;margin:0;padding:0}
.fx-qv .opt label{position:relative}.fx-qv .opt input{position:absolute;opacity:0;inset:0;margin:0;cursor:pointer}
.fx-qv .opt .s{display:grid;place-items:center;min-width:2.6em;padding:.45em .7em;border:1.5px solid var(--border);border-radius:calc(var(--radius) - 3px);font-size:.85em;font-weight:600;transition:all .2s}
.fx-qv .opt input:checked+.s{border-color:var(--primary);background:var(--primary);color:var(--on-primary)}
.fx-qv .opt input:focus-visible+.s{outline:2px solid var(--accent);outline-offset:2px}
.fx-qv .opt .c{width:1.9em;height:1.9em;border-radius:50%;padding:0;min-width:0;background:var(--c);box-shadow:inset 0 0 0 3px var(--surface)}
.fx-qv .opt input:checked+.c{background:var(--c);border-color:var(--primary)}
.fx-qv .buy{display:flex;gap:.6em;align-items:stretch}
.fx-qv .qty{display:inline-flex;align-items:center;border:1.5px solid var(--border);border-radius:var(--radius)}
.fx-qv .qty button{all:unset;cursor:pointer;width:2.2em;height:2.6em;text-align:center;font-size:1.05em}.fx-qv .qty button:focus-visible{outline:2px solid var(--accent)}.fx-qv .qty button:hover{color:var(--primary)}
.fx-qv .qty output{min-width:1.6em;text-align:center;font-weight:700;font-size:.95em}
.fx-qv .buy .btn{flex:1}.fx-qv .more{font-size:.85em;color:var(--primary);font-weight:700;text-decoration:none}
.fx-qv .x{position:absolute;right:.7em;top:.7em;z-index:3;width:2.3em;height:2.3em;border-radius:50%;border:0;background:var(--surface);cursor:pointer;color:var(--text);box-shadow:0 4px 12px -4px rgba(0,0,0,.4)}
@media(max-width:620px){.fx-qv .dlg{grid-template-columns:1fr}.fx-qv .dlg>.fx-art{min-height:9em}.fx-qv .gr{grid-template-columns:1fr 1fr}.fx-qv .gr .it:nth-child(3){display:none}}
@media(prefers-reduced-motion:reduce){.fx-qv .dlg,.fx-qv .qvb{transition:none}}

/* touch: :hover mirrored as .is-tap */
.fx-qv .btn.is-tap{border-color:var(--primary);color:var(--primary)}
.fx-qv .btn.pri.is-tap{background:color-mix(in srgb,var(--primary) 85%,var(--text));color:var(--on-primary)}
.fx-qv .it.is-tap .qvb{transform:translate(-50%,0)}
.fx-qv .qty button.is-tap{color:var(--primary)}

