(function(){var root=document.querySelector('.fx-qv'),pg=root.querySelector('.pg'),sc=root.querySelector('.scrim'),dlg=root.querySelector('.dlg'),op=null,q=1;
function focusables(c){return [].slice.call(c.querySelectorAll('button,input,select,textarea,a[href],[tabindex]:not([tabindex="-1"])')).filter(function(e){return !e.disabled&&e.offsetParent!==null})}
function trap(e,c){if(e.key!=='Tab')return;var f=focusables(c);if(!f.length)return;var a=f[0],z=f[f.length-1];
if(e.shiftKey&&document.activeElement===a){e.preventDefault();z.focus()}else if(!e.shiftKey&&document.activeElement===z){e.preventDefault();a.focus()}}

var out=root.querySelector('output'),add=root.querySelector('[data-add]'),art=dlg.querySelector('.fx-art');var arts=['','a2','a3'];
var items=root.querySelectorAll('.it');
function open(b){op=b;var it=b.closest('.it');dlg.querySelector('#qv-t').textContent=it.querySelector('.nm b').textContent;
var sp=it.querySelector('.nm span'),s=sp.querySelector('s');dlg.querySelector('#qv-p').innerHTML=sp.innerHTML;
art.className='fx-art '+it.querySelector('.fx-art').className.replace('fx-art','').trim();
q=1;out.textContent=1;add.textContent='Add to bag';sc.classList.add('open');sc.setAttribute('aria-hidden','false');pg.inert=true;requestAnimationFrame(function(){dlg.querySelector('.x').focus()})}
function close(){if(!sc.classList.contains('open'))return;sc.classList.remove('open');sc.setAttribute('aria-hidden','true');pg.inert=false;if(op)op.focus()}
root.querySelectorAll('.qvb').forEach(function(b){b.addEventListener('click',function(){open(b)})});
root.querySelectorAll('[data-close]').forEach(function(b){b.addEventListener('click',close)});
sc.addEventListener('mousedown',function(e){if(e.target===sc)close()});
root.querySelectorAll('[data-q]').forEach(function(b){b.addEventListener('click',function(){q=Math.max(1,Math.min(9,q+ +b.dataset.q));out.textContent=q})});
add.addEventListener('click',function(){add.textContent='Added ✓';setTimeout(function(){add.textContent='Add to bag'},1600)});
document.addEventListener('keydown',function(e){if(!sc.classList.contains('open'))return;if(e.key==='Escape')close();else trap(e,dlg)});})();
/* fx-touch */
(function(){if(window.__fxTap)return;window.__fxTap=1;var cur=[];function clr(){cur.forEach(function(e){e.classList.remove('is-tap')});cur=[]}
document.addEventListener('pointerdown',function(e){if(e.pointerType!=='touch')return;clr();var n=e.target.closest&&e.target.closest('.fx');if(!n)return;for(var el=e.target;el&&el!==n.parentNode;el=el.parentNode){if(el.classList){el.classList.add('is-tap');cur.push(el)}}},{passive:true});
document.addEventListener('pointerup',function(){setTimeout(clr,1400)},{passive:true})})();
